<?php
namespace qqworld_collector\module\collect_filter; class insert_template extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $position = isset($args['position']) ? $args['position'] : 'front'; $template = isset($args['template']) ? $args['template'] : ''; if ($template) { $template = get_post($template); switch ($position) { case 'front': $item = $template->post_content . $item; break; case 'back': $item = $item . $template->post_content; break; } } return $item; } } ?>